package com.hostelfind.model;
import jakarta.persistence.*;
@Entity @Table(name="claims") public class Claim { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne @JoinColumn(name="item_id",nullable=false) private Item item; @ManyToOne @JoinColumn(name="claimant_id",nullable=false) private User claimant; @Column(nullable=false,length=2000) private String proofOrMessage; @Enumerated(EnumType.STRING) @Column(nullable=false) private ClaimStatus status=ClaimStatus.PENDING; public Long getId(){return id;} public Item getItem(){return item;} public User getClaimant(){return claimant;} public String getProofOrMessage(){return proofOrMessage;} public ClaimStatus getStatus(){return status;} public void setItem(Item v){item=v;} public void setClaimant(User v){claimant=v;} public void setProofOrMessage(String v){proofOrMessage=v;} public void setStatus(ClaimStatus v){status=v;} }
